#include <iostream>

class Node {
public:
    explicit Node(int value = 0)
        : data{value}, nextPtr{nullptr} {}

    void setData(int value) { data = value; }
    int getData() const { return data; }

    void setNextPtr(Node* next) { nextPtr = next; }
    Node* getNextPtr() const { return nextPtr; }

private:
    int data;
    Node* nextPtr;
};

int main() {
    // Create two self-referential nodes
    Node firstNode{15};
    Node secondNode{10};

    // Link firstNode to secondNode
    firstNode.setNextPtr(&secondNode);

    // Ensure the terminal node link is nullptr (Common Programming Error 19.1 avoidance)
    secondNode.setNextPtr(nullptr);

    // Traverse the linked nodes starting from firstNode
    const Node* currentPtr = &firstNode;
    while (currentPtr != nullptr) {
        std::cout << "Node value: " << currentPtr->getData() << "\n";
        currentPtr = currentPtr->getNextPtr();
    }

    return 0;
}

#include <iostream>

struct Node {
    int data;
    Node* next;
    explicit Node(int val) : data{val}, next{nullptr} {}
};

// Insert at the front of the list: O(1) without shifting data
void insertAtFront(Node*& head, int value) {
    Node* newNode = new Node(value);
    newNode->next = head;
    head = newNode;
}

// Print all elements sequentially
void printList(const Node* head) {
    const Node* current = head;
    while (current != nullptr) {
        std::cout << current->data << " -> ";
        current = current->next;
    }
    std::cout << "nullptr\n";
}

// Deallocate list to prevent memory leaks
void freeList(Node*& head) {
    while (head != nullptr) {
        Node* temp = head;
        head = head->next;
        delete temp;
    }
}

int main() {
    Node* head = nullptr;

    // Demonstrating dynamic expansion without contiguous array reallocation
    insertAtFront(head, 30);
    insertAtFront(head, 20);
    insertAtFront(head, 10);

    std::cout << "List contents:\n";
    printList(head);

    freeList(head);
    return 0;
}
